(28793, 'Hebrews 10:38', 'Hebrews', 10, 38, 'د ایمان په وسیله به کوي ژوند زما نېکان او څوک چې مخ واړوي ما نه نو زه به نه یمه خوشحاله د هغه نه', 'د ایمان په وسیله به کوی ژوند زما نېکان او چوک چې مخ واروی ما نه نو زه به نه یمه خوشحاله د هغه نه', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Hebrews_10_38.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237835, 1761237835),
(28794, 'Hebrews 10:39', 'Hebrews', 10, 39, 'خو مونږ هغه خلک نه یو چې د خدای څخه مخ اړوي او تباه کیږي، بلکې مونږ ایمان لرو او ژغورل کېږو.', 'خو مونز هغه خلک نه یو چې د خدای چخه مخ اروی او تباه کیزی، بلکې مونز ایمان لرو او ژغورل کېزو.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Hebrews_10_39.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237835, 1761237835),
(28795, 'Matthew 7:1', 'Matthew', 7, 1, 'د نورو په هکله قضاوت مه کوئ، ترڅو تاسو تر قضاوت لاندې ونه نیول شئ.', 'د نورو په هکله قضاوت مه کوی، ترچو تاسو تر قضاوت لاندې ونه نیول شی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Matthew_7_1.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237835, 1761237835),
(28796, 'Matthew 7:2', 'Matthew', 7, 2, 'ځکه لکه څنګه چې تاسو نور خلک ملامتوئ، نو تاسو به هم ملامته کړای شئ. په هره پیمانه چې تاسو یې ورکوئ، نو په هماغه پیمانه به تاسو ته هم درکړل شي.', 'جکه لکه چنګه چې تاسو نور خلک ملامتوی، نو تاسو به هم ملامته کرای شی. په هره پیمانه چې تاسو یې ورکوی، نو په هماغه پیمانه به تاسو ته هم درکرل شی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Matthew_7_2.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237835, 1761237835),
(28797, 'Matthew 7:3', 'Matthew', 7, 3, 'ته ولې د خپل ورور په سترګه کې خسڼی ګورې، خو په خپله سترګه کې غټ لرګی لیدلی نه شې؟', 'ته ولې د خپل ورور په سترګه کې خسنی ګورې، خو په خپله سترګه کې غت لرګی لیدلی نه شې؟', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Matthew_7_3.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237835, 1761237835),
(28798, 'Matthew 7:4', 'Matthew', 7, 4, 'یا ته څنګه خپل ورور ته ویلی شې چې اجازه راکړه ستا د سترګې نه خسڼی راوباسم، حال دا چې ستا په خپله سترګه کې لرګی دی؟', 'یا ته چنګه خپل ورور ته ویلی شې چې اجازه راکره ستا د سترګې نه خسنی راوباسم، حال دا چې ستا په خپله سترګه کې لرګی دی؟', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Matthew_7_4.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237835, 1761237835),
(28799, 'Matthew 7:5', 'Matthew', 7, 5, 'ای منافقه، لومړی د خپلې سترګې نه لرګی وباسه، نو بیا به ستا سترګې هم وغړیږي چې د خپل ورور د سترګې نه خسڼی وباسې.', 'ای منافقه، لومری د خپلې سترګې نه لرګی وباسه، نو بیا به ستا سترګې هم وغریزی چې د خپل ورور د سترګې نه خسنی وباسې.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Matthew_7_5.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237835, 1761237835),
(28800, 'Matthew 7:6', 'Matthew', 7, 6, 'سپيانو ته سپېڅلي شیان مه ورکوئ او خپلې مرغلرې خوګانو ته مه وراچوئ، هسې نه چې هغه تر‌پښو لاندې کړي او بېرته راوګرځي او په تاسو باندې حمله وکړي. وغواړئ، ولټوئ او وټکوئ (لوقا ۱۱‏:‌۹‌‏-‌۱۳)', 'سپیانو ته سپېچلی شیان مه ورکوی او خپلې مرغلرې خوګانو ته مه وراچوی، هسې نه چې هغه تر‌پشو لاندې کری او بېرته راوګرجی او په تاسو باندې حمله وکری. وغواری، ولتوی او وتکوی (لوقا ۱۱‏:‌۹‌‏-‌۱۳)', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Matthew_7_6.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237835, 1761237835),
(28801, 'Matthew 7:7', 'Matthew', 7, 7, 'وغواړئ، نو تاسو ته به درکړل شي. ولټوئ نو پیدا به یې کړئ. وټکوئ نو دروازه به درته خلاصه شي.', 'وغواری، نو تاسو ته به درکرل شی. ولتوی نو پیدا به یې کری. وتکوی نو دروازه به درته خلاصه شی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Matthew_7_7.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237835, 1761237835),
(28802, 'Matthew 7:8', 'Matthew', 7, 8, 'ځکه هرڅوک چې څه وغواړي، نو لاسته به یې راوړي او څوک یې چې ولټوي، نو پیدا به یې کړي او څوک چې دروازه وټکوي، نو ورته خلاصه به شي.', 'جکه هرچوک چې چه وغواری، نو لاسته به یې راوری او چوک یې چې ولتوی، نو پیدا به یې کری او چوک چې دروازه وتکوی، نو ورته خلاصه به شی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Matthew_7_8.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237835, 1761237835),
