(28811, 'Matthew 7:17', 'Matthew', 7, 17, 'نو هره ښه ونه ښه مېوه نیسي او خرابه ونه خرابه مېوه نیسي.', 'نو هره شه ونه شه مېوه نیسی او خرابه ونه خرابه مېوه نیسی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Matthew_7_17.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237835, 1761237835),
(28812, 'Matthew 7:18', 'Matthew', 7, 18, 'ښه ونه خرابه مېوه نه شي نیولی او نه خرابه ونه ښه مېوه نیولی شي.', 'شه ونه خرابه مېوه نه شی نیولی او نه خرابه ونه شه مېوه نیولی شی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Matthew_7_18.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237835, 1761237835),
(28813, 'Matthew 7:19', 'Matthew', 7, 19, 'کومه ونه چې ښه مېوه نه نیسي، نو هغه ونه به ووهل شي او په اور کې به واچول شي.', 'کومه ونه چې شه مېوه نه نیسی، نو هغه ونه به ووهل شی او په اور کې به واچول شی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Matthew_7_19.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237835, 1761237835),
